var FAVOURITES_GROUP_ID = "favourites";
function filterImageTemplates(options, query, groupId, groups = [], favouriteIds = []) {
  const needle = query.trim().toLowerCase();
  const groupLabel = (id) => groups.find((g) => g.id === id)?.label ?? "";
  const matches = (o) => !needle || [o.label, ...o.badges ?? [], groupLabel(o.groupId)].some((text) => text.toLowerCase().includes(needle));
  if (groupId === FAVOURITES_GROUP_ID) {
    return favouriteIds.flatMap((id) => options.filter((o) => o.id === id && matches(o)));
  }
  return options.filter((o) => (!groupId || o.groupId === groupId) && matches(o));
}

